const [design, prdOpen, unknownOpen, prdAll, unknownAll] = await Promise.all([
  gm.read_file({ path: '/workspace/gm/DESIGN.md' }),
  gm.prd_list({ status: 'open' }),
  gm.unknown_list({ status: 'open' }),
  gm.prd_list({ status: 'all' }),
  gm.unknown_list({ status: 'all' })
]);
const lines = (design.output || '').split(String.fromCharCode(10));
const plan = 'Batch plan: 0 open row(s), planned before any work starts.';
await gm.run_shell({ command: 'printf ' + JSON.stringify(plan + String.fromCharCode(10)) });
return {
  plan,
  design: {
    ok: design.ok,
    line137: lines[136] || '',
    line156: lines[155] || '',
    context: lines.slice(130, 160).map((text, i) => ({ line: 131 + i, text })).filter((row) => row.text.length > 0)
  },
  rows: { prdOpen: prdOpen.output || prdOpen, unknownOpen: unknownOpen.output || unknownOpen, prdAll: prdAll.output || prdAll, unknownAll: unknownAll.output || unknownAll }
};

const inspect = `python3 -I - <<'PY'
from pathlib import Path
import json
p = Path('/workspace/gm/DESIGN.md')
lines = p.read_text(encoding='utf-8').splitlines()
print(json.dumps({'exists': p.exists(), 'lines': len(lines), 'line137': lines[136] if len(lines) > 136 else '', 'line156': lines[155] if len(lines) > 155 else '', 'context': [{'line': n + 1, 'text': lines[n]} for n in range(max(0, min(130, len(lines) - 1)), min(160, len(lines)))]}, separators=(',', ':')))
PY`;
const result = await gm.run_shell({ command: inspect, timeoutMs: 120000 });
return { exitCode: result.exitCode, output: (result.output || '').slice(0, 6000), error: result.error };
